import numpy as np
F=np.load('feats.npz'); y=F['y']; FOLDS=np.load('folds_rep.npy')
G={k:F[k].astype(np.float64) for k in F.files if k!='y'}
def stdz(X,tr): m=X[tr].mean(0); s=X[tr].std(0)+1e-6; return (X-m)/s
def ridge_pred(Xtr,Y,lam,Xte):
    xm=Xtr.mean(0); Xc=Xtr-xm; ym=Y.mean(0)
    n,d=Xc.shape
    if d<=n: Wt=np.linalg.solve(Xc.T@Xc+lam*np.eye(d),Xc.T@(Y-ym))
    else: Wt=Xc.T@np.linalg.solve(Xc@Xc.T+lam*np.eye(n),Y-ym)
    return (Xte-xm)@Wt+ym, Wt
def rcv_lin(keys,lams,w=None):
    w=w or [1]*len(keys); res={l:0 for l in lams}
    for fo in FOLDS:
        for f in range(5):
            tr=fo!=f; te=fo==f
            X=np.concatenate([wi*stdz(G[k],tr) for k,wi in zip(keys,w)],1)
            Y=np.eye(8)[y[tr]]-1/8
            for l in lams: res[l]+=(ridge_pred(X[tr],Y,l,X[te])[0].argmax(1)==y[te]).sum()
    return {l:round(res[l]/len(y)/len(FOLDS),4) for l in lams}
print('C9M9', rcv_lin(['C9','M9'],[300,1000]))
for k in ['M0','M1','M2','M3','M4','M6']:
    print('C9M9+'+k, rcv_lin(['C9','M9',k],[300,1000,3000]))
